const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// Helper to get all todo items
function getTodos(doc) {
  return doc.querySelectorAll('.todo-list li');
}

// Helper to get a specific todo
function getTodo(doc, index) {
  return getTodos(doc)[index];
}

// Helper to get todo title
function getTodoTitle(doc, index) {
  const todo = getTodo(doc, index);
  return todo.querySelector('label').textContent;
}

// Helper to check if todo is completed
function isTodoCompleted(doc, index) {
  return getTodo(doc, index).classList.contains('completed');
}

// Helper to check if todo is in editing mode
function isTodoEditing(doc, index) {
  return getTodo(doc, index).classList.contains('editing');
}

// Helper to click an element
function click(el) {
  el.dispatchEvent(new MouseEvent('click', { bubbles: true }));
}

// Helper to set value and dispatch input event
function setInputValue(input, value) {
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
    window.HTMLInputElement.prototype, 'value'
  ).set;
  nativeInputValueSetter.call(input, value);
  input.dispatchEvent(new Event('input', { bubbles: true }));
}

// Helper to dispatch keydown event
function pressKey(el, keyCode) {
  el.dispatchEvent(new KeyboardEvent('keydown', {
    keyCode: keyCode,
    which: keyCode,
    bubbles: true
  }));
}

// Helper to dispatch blur event
function blur(el) {
  el.dispatchEvent(new Event('blur', { bubbles: true }));
}

Given('the app is loaded with no todos', function () {
  this.loadApp();
  // Ensure clean state
  this.window.localStorage.removeItem('todos-vanillajs');
  this.loadApp();
});

Given('the app has todos {string}', function (titles) {
  const todoTitles = titles.split('", "').map(t => t.replace(/^"|"$/g, ''));
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(
    todoTitles.map((title, i) => ({ id: i + 1, title, completed: false }))
  ));
  this.loadApp();
});

Given('the app has todos {string} that are all completed', function (titles) {
  const todoTitles = titles.split('", "').map(t => t.replace(/^"|"$/g, ''));
  this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(
    todoTitles.map((title, i) => ({ id: i + 1, title, completed: true }))
  ));
  this.loadApp();
});

When('I type {string} in the new todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  setInputValue(input, text);
  pressKey(input, 13); // ENTER_KEY
});

When('I click the toggle all checkbox', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  click(toggleAll);
});

When('I click the toggle for todo at index {int}', function (index) {
  const todo = getTodo(this.document, index);
  const toggle = todo.querySelector('.toggle');
  click(toggle);
});

When('I click the destroy button for todo at index {int}', function (index) {
  const todo = getTodo(this.document, index);
  const destroy = todo.querySelector('.destroy');
  click(destroy);
});

When('I double-click the label for todo at index {int}', function (index) {
  const todo = getTodo(this.document, index);
  const label = todo.querySelector('label');
  label.dispatchEvent(new MouseEvent('dblclick', { bubbles: true }));
});

When('I clear the edit input and type {string} and press Enter', function (text) {
  const todo = getTodo(this.document, 0);
  const editInput = todo.querySelector('.edit');
  setInputValue(editInput, text);
  pressKey(editInput, 13); // ENTER_KEY
});

When('I clear the edit input and type {string} and blur', function (text) {
  const todo = getTodo(this.document, 0);
  const editInput = todo.querySelector('.edit');
  setInputValue(editInput, text);
  blur(editInput);
});

When('I clear the edit input and press Enter', function () {
  const todo = getTodo(this.document, 0);
  const editInput = todo.querySelector('.edit');
  setInputValue(editInput, '');
  pressKey(editInput, 13); // ENTER_KEY
});

When('I clear the edit input and type {string} and press Escape', function (text) {
  const todo = getTodo(this.document, 0);
  const editInput = todo.querySelector('.edit');
  setInputValue(editInput, text);
  pressKey(editInput, 27); // ESCAPE_KEY
});

When('I click the clear completed button', function () {
  const clearBtn = this.document.querySelector('.clear-completed');
  click(clearBtn);
});

When('I reload the app', function () {
  // Get current localStorage state before reload
  const saved = this.window.localStorage.getItem('todos-vanillajs');
  // Reload the app (preserves localStorage in happy-dom)
  this.loadApp();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

Then('the main section should be hidden', function () {
  const main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none');
});

Then('the footer should be hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.strictEqual(footer.style.display, 'none');
});

Then('the todo list should contain {int} item(s)', function (count) {
  const todos = getTodos(this.document);
  assert.strictEqual(todos.length, count);
});

Then('the todo at index {int} should have title {string}', function (index, title) {
  assert.strictEqual(getTodoTitle(this.document, index), title);
});

Then('the new todo input should be empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

Then('the todo at index {int} should be completed', function (index) {
  assert.strictEqual(isTodoCompleted(this.document, index), true);
});

Then('the todo at index {int} should be active', function (index) {
  assert.strictEqual(isTodoCompleted(this.document, index), false);
});

Then('all todos should be completed', function () {
  const todos = getTodos(this.document);
  todos.forEach(todo => {
    assert.strictEqual(todo.classList.contains('completed'), true);
  });
});

Then('all todos should be active', function () {
  const todos = getTodos(this.document);
  todos.forEach(todo => {
    assert.strictEqual(todo.classList.contains('completed'), false);
  });
});

Then('the toggle all checkbox should be checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.strictEqual(toggleAll.checked, true);
});

Then('the toggle all checkbox should be unchecked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.strictEqual(toggleAll.checked, false);
});

Then('the todo at index {int} should be in editing mode', function (index) {
  assert.strictEqual(isTodoEditing(this.document, index), true);
});

Then('the todo at index {int} should not be in editing mode', function (index) {
  assert.strictEqual(isTodoEditing(this.document, index), false);
});

Then('the edit input for todo at index {int} should contain {string}', function (index, text) {
  const todo = getTodo(this.document, index);
  const editInput = todo.querySelector('.edit');
  assert.strictEqual(editInput.value, text);
});

Then('the counter should show {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert.strictEqual(counter.textContent.trim(), text);
});

Then('the clear completed button should be hidden', function () {
  const clearBtn = this.document.querySelector('.clear-completed');
  assert.strictEqual(clearBtn.style.display, 'none');
});

Then('the clear completed button should be visible', function () {
  const clearBtn = this.document.querySelector('.clear-completed');
  assert.notStrictEqual(clearBtn.style.display, 'none');
});

Then('the {string} filter link should be selected', function (linkText) {
  const links = this.document.querySelectorAll('.filters a');
  links.forEach(link => {
    if (link.textContent === linkText) {
      assert.strictEqual(link.classList.contains('selected'), true);
    } else {
      assert.strictEqual(link.classList.contains('selected'), false);
    }
  });
});

(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  var Utils = {
    uuid: function () {
      return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
        var r = Math.random() * 16 | 0;
        var v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
      });
    },
    store: function (namespace, data) {
      if (arguments.length > 1) {
        return localStorage.setItem(namespace, JSON.stringify(data));
      } else {
        var store = localStorage.getItem(namespace);
        return (store && JSON.parse(store)) || [];
      }
    }
  };

  var App = {
    init: function () {
      this.todos = Utils.store(STORAGE_KEY);
      this.bindEvents();
      this.render();
    },
    bindEvents: function () {
      var todoList = document.querySelector('.todo-list');
      var newTodo = document.querySelector('.new-todo');
      var toggleAll = document.querySelector('#toggle-all');
      var clearCompleted = document.querySelector('.clear-completed');

      newTodo.addEventListener('keyup', this.create.bind(this));
      todoList.addEventListener('click', this.destroy.bind(this));
      todoList.addEventListener('click', this.toggle.bind(this));
      todoList.addEventListener('dblclick', this.edit.bind(this));
      todoList.addEventListener('keyup', this.editKeyup.bind(this));
      todoList.addEventListener('focusout', this.editBlur.bind(this));
      todoList.addEventListener('click', this.destroy.bind(this));
      toggleAll.addEventListener('change', this.toggleAll.bind(this));
      clearCompleted.addEventListener('click', this.clearCompleted.bind(this));

      window.addEventListener('hashchange', this.filter.bind(this));
    },
    render: function () {
      var todoList = document.querySelector('.todo-list');
      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var toggleAll = document.querySelector('#toggle-all');
      var newTodo = document.querySelector('.new-todo');

      var html = '';
      var completed = 0;
      var active = 0;

      this.todos.forEach(function (todo) {
        if (todo.completed) {
          completed++;
        } else {
          active++;
        }

        var completedClass = todo.completed ? ' completed' : '';
        html += '<li data-id="' + todo.id + '" class="' + completedClass + '">' +
          '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + this.escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
          '</div>' +
          '<input class="edit" value="' + this.escapeHtml(todo.title) + '">' +
          '</li>';
      }.bind(this));

      todoList.innerHTML = html;

      if (this.todos.length > 0) {
        main.style.display = '';
        footer.style.display = '';
      } else {
        main.style.display = 'none';
        footer.style.display = 'none';
      }

      toggleAll.checked = completed === this.todos.length && this.todos.length > 0;

      var count = document.querySelector('.todo-count');
      count.innerHTML = '<strong>' + active + '</strong> ' + (active === 1 ? 'item' : 'items') + ' left';

      var clearBtn = document.querySelector('.clear-completed');
      clearBtn.style.display = completed > 0 ? '' : 'none';

      this.filter();
    },
    escapeHtml: function (str) {
      var div = document.createElement('div');
      div.appendChild(document.createTextNode(str));
      return div.innerHTML;
    },
    create: function (e) {
      var input = e.target;
      var val = input.value.trim();

      if (e.which !== ENTER_KEY || !val) {
        return;
      }

      this.todos.push({
        id: Utils.uuid(),
        title: val,
        completed: false
      });

      input.value = '';
      Utils.store(STORAGE_KEY, this.todos);
      this.render();
    },
    destroy: function (e) {
      if (e.target.className !== 'destroy') {
        return;
      }

      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');

      this.todos = this.todos.filter(function (todo) {
        return todo.id !== id;
      });

      Utils.store(STORAGE_KEY, this.todos);
      this.render();
    },
    toggle: function (e) {
      if (e.target.className !== 'toggle') {
        return;
      }

      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');

      this.todos.forEach(function (todo) {
        if (todo.id === id) {
          todo.completed = !todo.completed;
        }
      });

      Utils.store(STORAGE_KEY, this.todos);
      this.render();
    },
    toggleAll: function (e) {
      var checked = e.target.checked;

      this.todos.forEach(function (todo) {
        todo.completed = checked;
      });

      Utils.store(STORAGE_KEY, this.todos);
      this.render();
    },
    edit: function (e) {
      if (e.target.tagName !== 'LABEL') {
        return;
      }

      var li = e.target.closest('li');
      li.classList.add('editing');

      var editInput = li.querySelector('.edit');
      editInput.focus();
    },
    editKeyup: function (e) {
      if (e.target.className !== 'edit') {
        return;
      }

      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');

      if (e.which === ENTER_KEY) {
        e.target.blur();
      } else if (e.which === ESCAPE_KEY) {
        this.cancelEdit(e.target);
      }
    },
    editBlur: function (e) {
      if (e.target.className !== 'edit') {
        return;
      }

      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      var val = e.target.value.trim();

      if (val) {
        this.todos.forEach(function (todo) {
          if (todo.id === id) {
            todo.title = val;
          }
        });
        Utils.store(STORAGE_KEY, this.todos);
      } else {
        this.todos = this.todos.filter(function (todo) {
          return todo.id !== id;
        });
        Utils.store(STORAGE_KEY, this.todos);
      }

      li.classList.remove('editing');
      this.render();
    },
    cancelEdit: function (input) {
      var li = input.closest('li');
      var id = li.getAttribute('data-id');
      var todo = this.todos.find(function (t) {
        return t.id === id;
      });

      if (todo) {
        input.value = todo.title;
      }

      li.classList.remove('editing');
    },
    clearCompleted: function () {
      this.todos = this.todos.filter(function (todo) {
        return !todo.completed;
      });

      Utils.store(STORAGE_KEY, this.todos);
      this.render();
    },
    filter: function () {
      var hash = window.location.hash || '#/';
      var todoList = document.querySelector('.todo-list');
      var links = document.querySelectorAll('.filters a');

      links.forEach(function (link) {
        if (link.getAttribute('href') === hash) {
          link.classList.add('selected');
        } else {
          link.classList.remove('selected');
        }
      });

      var todos = todoList.querySelectorAll('li');
      todos.forEach(function (li) {
        var id = li.getAttribute('data-id');
        var todo = this.todos.find(function (t) {
          return t.id === id;
        });

        if (!todo) return;

        var show = true;
        if (hash === '#/active' && todo.completed) {
          show = false;
        } else if (hash === '#/completed' && !todo.completed) {
          show = false;
        }

        li.style.display = show ? '' : 'none';
      }.bind(this));
    }
  };

  App.init();
})();

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// Helper to get all todo items
function getTodos(doc) {
  return doc.querySelectorAll('.todo-list li');
}

// Helper to get a specific todo
function getTodo(doc, index) {
  return getTodos(doc)[index];
}

// Helper to get todo title
function getTodoTitle(doc, index) {
  const todo = getTodo(doc, index);
  return todo.querySelector('label').textContent;
}

// Helper to check if todo is completed
function isTodoCompleted(doc, index) {
  return getTodo(doc, index).classList.contains('completed');
}

// Helper to check if todo is in editing mode
function isTodoEditing(doc, index) {
  return getTodo(doc, index).classList.contains('editing');
}

// Helper to click an element
function click(el) {
  el.dispatchEvent(new MouseEvent('click', { bubbles: true }));
}

// Helper to set value and dispatch input event
function setInputValue(win, input, value) {
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
    win.HTMLInputElement.prototype, 'value'
  ).set;
  nativeInputValueSetter.call(input, value);
  input.dispatchEvent(new Event('input', { bubbles: true }));
}

// Helper to dispatch keydown event
function pressKey(el, keyCode) {
  el.dispatchEvent(new KeyboardEvent('keydown', {
    keyCode: keyCode,
    which: keyCode,
    bubbles: true
  }));
}

// Helper to dispatch blur event
function blur(el) {
  el.dispatchEvent(new Event('blur', { bubbles: true }));
}

// Helper to parse todo titles from a quoted string list
function parseTitles(titlesStr) {
  return titlesStr.split('", "').map(t => t.replace(/^"|"$/g, ''));
}

Given('the app is loaded with no todos', function () {
  this.loadApp();
  // Ensure clean state
  this.window.localStorage.removeItem('todos-vanillajs');
  this.loadApp();
});

