const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// Helper to get all todo items
function getTodos(doc) {
  return doc.querySelectorAll('.todo-list li');
}

// Helper to get a specific todo
function getTodo(doc, index) {
  return getTodos(doc)[index];
}

// Helper to get todo title
function getTodoTitle(doc, index) {
  const todo = getTodo(doc, index);
  return todo.querySelector('label').textContent;
}

// Helper to check if todo is completed
function isTodoCompleted(doc, index) {
  return getTodo(doc, index).classList.contains('completed');
}

// Helper to check if todo is in editing mode
function isTodoEditing(doc, index) {
  return getTodo(doc, index).classList.contains('editing');
}

// Helper to click an element
function clickEl(win, el) {
  el.dispatchEvent(new win.MouseEvent('click', { bubbles: true }));
}

// Helper to set value and dispatch input event
function setInputValue(win, input, value) {
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(
    win.HTMLInputElement.prototype, 'value'
  ).set;
  nativeInputValueSetter.call(input, value);
  input.dispatchEvent(new win.Event('input', { bubbles: true }));
}

// Helper to dispatch keydown event
function pressKey(win, el, keyCode) {
  el.dispatchEvent(new win.KeyboardEvent('keydown', {
    keyCode: keyCode,
    which: keyCode,
    bubbles: true
  }));
}

// Helper to dispatch blur event
function blurEl(win, el) {
  el.dispatchEvent(new win.Event('blur', { bubbles: true }));
}

// Helper to set up localStorage and load app with given todo titles
function setupTodos(world, titles, completed) {
  // Load app first (creates new Window)
  world.loadApp();
  // Set localStorage data
  const todoData = titles.map((title, i) => ({
    id: String(i + 1),
    title,
    completed: completed || false
  }));
  world.window.localStorage.setItem('todos-vanillajs', JSON.stringify(todoData));
  // Reload so the app reads the stored data
  world.loadApp();
}

Given('the app is loaded with no todos', function () {
  this.loadApp();
  this.window.localStorage.removeItem('todos-vanillajs');
  this.loadApp();
});

Given('the app has todos {string}', function (t1) {
  setupTodos(this, [t1]);
});

Given('the app has todos {string}, {string}', function (t1, t2) {
  setupTodos(this, [t1, t2]);
});

Given('the app has todos {string}, {string}, {string}', function (t1, t2, t3) {
  setupTodos(this, [t1, t2, t3]);
});

Given('the app has todos {string} that are all completed', function (t1) {
  setupTodos(this, [t1], true);
});

Given('the app has todos {string}, {string} that are all completed', function (t1, t2) {
  setupTodos(this, [t1, t2], true);
});

When('I type {string} in the new todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  setInputValue(this.window, input, text);
  pressKey(this.window, input, 13); // ENTER_KEY
});

When('I click the toggle all checkbox', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  clickEl(this.window, toggleAll);
});

When('I click the toggle for todo at index {int}', function (index) {
  const todo = getTodo(this.document, index);
  const toggle = todo.querySelector('.toggle');
  clickEl(this.window, toggle);
});

When('I click the destroy button for todo at index {int}', function (index) {
  const todo = getTodo(this.document, index);
  const destroy = todo.querySelector('.destroy');
  clickEl(this.window, destroy);
});

When('I double-click the label for todo at index {int}', function (index) {
  const todo = getTodo(this.document, index);
  const label = todo.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I clear the edit input and type {string} and press Enter', function (text) {
  const todo = getTodo(this.document, 0);
  const editInput = todo.querySelector('.edit');
  setInputValue(this.window, editInput, text);
  pressKey(this.window, editInput, 13); // ENTER_KEY
});

When('I clear the edit input and type {string} and blur', function (text) {
  const todo = getTodo(this.document, 0);
  const editInput = todo.querySelector('.edit');
  setInputValue(this.window, editInput, text);
  blurEl(this.window, editInput);
});

When('I clear the edit input and press Enter', function () {
  const todo = getTodo(this.document, 0);
  const editInput = todo.querySelector('.edit');
  setInputValue(this.window, editInput, '');
  pressKey(this.window, editInput, 13); // ENTER_KEY
});

When('I clear the edit input and type {string} and press Escape', function (text) {
  const todo = getTodo(this.document, 0);
  const editInput = todo.querySelector('.edit');
  setInputValue(this.window, editInput, text);
  pressKey(this.window, editInput, 27); // ESCAPE_KEY
});

When('I click the clear completed button', function () {
  const clearBtn = this.document.querySelector('.clear-completed');
  clickEl(this.window, clearBtn);
});

When('I reload the app', function () {
  this.loadApp();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

Then('the main section should be hidden', function () {
  const main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none');
});

Then('the footer should be hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.strictEqual(footer.style.display, 'none');
});

Then('the todo list should contain {int} items', function (count) {
  const todos = getTodos(this.document);
  assert.strictEqual(todos.length, count);
});

Then('the todo at index {int} should have title {string}', function (index, title) {
  assert.strictEqual(getTodoTitle(this.document, index), title);
});

Then('the new todo input should be empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '');
});

Then('the todo at index {int} should be completed', function (index) {
  assert.strictEqual(isTodoCompleted(this.document, index), true);
});

Then('the todo at index {int} should be active', function (index) {
  assert.strictEqual(isTodoCompleted(this.document, index), false);
});

Then('all todos should be completed', function () {
  const todos = getTodos(this.document);
  todos.forEach(todo => {
    assert.strictEqual(todo.classList.contains('completed'), true);
  });
});

Then('all todos should be active', function () {
  const todos = getTodos(this.document);
  todos.forEach(todo => {
    assert.strictEqual(todo.classList.contains('completed'), false);
  });
});

Then('the toggle all checkbox should be checked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.strictEqual(toggleAll.checked, true);
});

Then('the toggle all checkbox should be unchecked', function () {
  const toggleAll = this.document.querySelector('#toggle-all');
  assert.strictEqual(toggleAll.checked, false);
});

Then('the todo at index {int} should be in editing mode', function (index) {
  assert.strictEqual(isTodoEditing(this.document, index), true);
});

Then('the todo at index {int} should not be in editing mode', function (index) {
  assert.strictEqual(isTodoEditing(this.document, index), false);
});

Then('the edit input for todo at index {int} should contain {string}', function (index, text) {
  const todo = getTodo(this.document, index);
  const editInput = todo.querySelector('.edit');
  assert.strictEqual(editInput.value, text);
});

Then('the counter should show {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert.strictEqual(counter.textContent.trim(), text);
});

Then('the clear completed button should be hidden', function () {
  const clearBtn = this.document.querySelector('.clear-completed');
  assert.strictEqual(clearBtn.style.display, 'none');
});

Then('the clear completed button should be visible', function () {
  const clearBtn = this.document.querySelector('.clear-completed');
  assert.notStrictEqual(clearBtn.style.display, 'none');
});

Then('the {string} filter link should be selected', function (linkText) {
  const links = this.document.querySelectorAll('.filters a');
  links.forEach(link => {
    if (link.textContent === linkText) {
      assert.strictEqual(link.classList.contains('selected'), true);
    } else {
      assert.strictEqual(link.classList.contains('selected'), false);
    }
  });
});

